mapper.sql:
WHERE t.user_id = #{userId}
  AND t.transacted_at >= #{condition.startDateTime}
  AND t.transacted_at < #{condition.endDateTime}

    AND t.expense_category_id = #{condition.categoryId}

mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM `transaction`
WHERE user_id = #{userId}
    AND transaction_type IN ('WITHDRAWAL', 'PAYMENT')
    AND transacted_at >= #{startDateTime}
    AND transacted_at < #{endDateTime}
